package com.skyreserve.service;
import com.skyreserve.model.*; import com.skyreserve.repository.UserRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.util.*;
@Service public class UserService { private final UserRepository repo; private final PasswordEncoder encoder; public UserService(UserRepository r,PasswordEncoder e){repo=r;encoder=e;} public User register(String name,String email,String password,String phone){if(repo.findByEmail(email).isPresent())throw new IllegalArgumentException("Email already registered"); User u=new User(name,email,encoder.encode(password),Role.USER);u.setPhone(phone);return repo.save(u);} public Optional<User> find(String email){return repo.findByEmail(email);} public long count(){return repo.count();} public List<User> all(){return repo.findAll();} }